class Storage(dict):
    pass
class Middle(Storage):
    pass
class Repository(Middle):
    def __init__(self):
        self._data = {}
    def read(self, key):
        return self._data.get(key, 'UNKNOWN')
    def lookup(self, key):
        return self.get(key, 'UNKNOWN')

class Repository:
    def __init__(self):
        self._data: dict[str,str] = {}
    def get(self, key):
        return self._data.get(key, 'UNKNOWN')
def read(value: Repository):
    return value.get('required')

from typing import Optional, TypedDict
class Payload(TypedDict):
    id: str
def consume(record: Payload) -> Optional[str]:
    return record.get('id', None)

from typing import Optional
def consume(record: dict[str,str], key: str) -> Optional[str]:
    return record.get(key, 'UNKNOWN')

from typing import Optional, TypedDict
class Payload(TypedDict):
    id: str
class Repository:
    def __init__(self):
        self._data: Payload = {'id': 'A'}
    def read(self) -> Optional[str]:
        return self._data.get('id', None)

class MethodMixin:
    def get(self, key):
        return key
class MappingBase(dict):
    pass
class Combination(MethodMixin, MappingBase):
    pass
def execute(value: Combination):
    return value.get('id')

